package com.pointverse.app;

import android.animation.ValueAnimator;
import android.app.*;
import android.content.Context;
import android.graphics.*;
import android.os.SystemClock;
import android.provider.Settings;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.function.Consumer;

/** iOS interaction contract: universe pan, surface rotation, target dolly, stable spherical clusters. */
final class UniverseCanvas extends View {
    final UniverseScene scene;final UniverseScene.State state;final boolean mind;
    private final Paint paint=new Paint(3);private final Consumer<String> select;private final float density;
    private final GestureDetector gestures;private boolean pinching;private int pinchFirst=-1,pinchSecond=-1;private double previousSpan;
    private ValueAnimator flight;private UniverseScene.Planet dragged,scaleTarget;private boolean multi,dragging;private float lastX,lastY,downX,downY;private long previousTick;
    private String hint="";private final List<LeafHit> leafHits=new ArrayList<>();private final List<Dialog> dialogs=new ArrayList<>();
    private final Map<String,Branch> branches=new LinkedHashMap<>();private final List<Box> boxes=new ArrayList<>();private final Map<String,Box> boxIndex=new HashMap<>();private RectF detailOpen=new RectF();
    static final class LeafHit {final UniverseScene.Planet planet;final UniverseScene.Cluster cluster;final float x,y;LeafHit(UniverseScene.Planet p,UniverseScene.Cluster cluster,float x,float y){planet=p;this.cluster=cluster;this.x=x;this.y=y;}}
    static final class Branch {final String id,title,level,parent,point;final int count;final List<String> children=new ArrayList<>();Branch(String id,String title,String level,String parent,String point,int count){this.id=id;this.title=title;this.level=level;this.parent=parent;this.point=point;this.count=count;}}
    static final class Box {final String id;final float x,y;Box(String id,float x,float y){this.id=id;this.x=x;this.y=y;}}
    UniverseCanvas(Context c,List<PointStore.Point> points,SemanticIndex index,boolean mind,Consumer<String> select){this(c,points,index,mind,new UniverseScene.State(),select);}
    UniverseCanvas(Context c,List<PointStore.Point> points,SemanticIndex index,boolean mind,UniverseScene.State state,Consumer<String> select){
        super(c);this.state=state;this.mind=mind;this.select=select;density=getResources().getDisplayMetrics().density;scene=new UniverseScene(points,index,state);setFocusable(true);setContentDescription(mind?"层级脑图，拖动平移，双指缩放，点卡片查看，点箭头展开或收起":"语义宇宙，拖动空白平移，点星球靠近，拖动星球表面旋转，双指缩放，点想法查看原文");
        buildTree();
        gestures=new GestureDetector(c,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(MotionEvent e){return true;}public boolean onSingleTapUp(MotionEvent e){if(!multi&&!dragging)tap(e.getX()/density,e.getY()/density);return true;}});
    }
    float w(){return getWidth()/density;}float h(){return getHeight()/density;}
    private boolean reduced(){return Settings.Global.getFloat(getContext().getContentResolver(),Settings.Global.ANIMATOR_DURATION_SCALE,1)==0;}
    private void pause(){state.pauseUntil=SystemClock.uptimeMillis()+6000;}
    private final Runnable orbit=new Runnable(){public void run(){if(mind||!isShown()||!hasWindowFocus())return;long now=SystemClock.uptimeMillis();if(previousTick!=0&&!mind&&!reduced()){double delta=UniverseScene.orbitDelta(previousTick/1000.0,now/1000.0,state.pauseUntil/1000.0);scene.advance(delta);}previousTick=now;invalidate();postDelayed(this,50);}};
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();previousTick=0;removeCallbacks(orbit);post(orbit);}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);removeCallbacks(orbit);previousTick=0;if(focus)post(orbit);}
    @Override protected void onDetachedFromWindow(){removeCallbacks(orbit);cancelFlight();for(Dialog d:dialogs)if(d.isShowing())d.dismiss();dialogs.clear();super.onDetachedFromWindow();}
    @Override protected void onSizeChanged(int width,int height,int oldWidth,int oldHeight){super.onSizeChanged(width,height,oldWidth,oldHeight);if(!state.initialized&&width>0&&height>0){if(mind)fitTree();else{double[] camera=scene.overview(w(),h());state.cameraX=camera[0];state.cameraY=camera[1];state.distance=camera[2];}state.initialized=true;}}
    private void cancelFlight(){if(flight!=null){flight.cancel();flight=null;}}
    private void fly(double[] destination){pause();cancelFlight();double sx=state.cameraX,sy=state.cameraY,sd=state.distance,base=Math.min(sd,destination[2])-Math.max(1,Math.abs(sd-destination[2]));double duration=Math.max(.4,Math.min(2.4,1.1+Math.abs(Math.log(Math.max(.01,destination[2])/Math.max(.01,sd)))*.18));if(reduced()){state.cameraX=destination[0];state.cameraY=destination[1];state.distance=destination[2];invalidate();return;}flight=ValueAnimator.ofFloat(0,1);flight.setDuration((long)(duration*1000));flight.setInterpolator(new android.view.animation.LinearInterpolator());flight.addUpdateListener(a->{double t=(float)a.getAnimatedValue(),smooth=t*t*(3-2*t);state.cameraX=sx+(destination[0]-sx)*smooth;state.cameraY=sy+(destination[1]-sy)*smooth;state.distance=base+UniverseScene.flight(sd-base,destination[2]-base,t);invalidate();});flight.start();}
    void approach(UniverseScene.Planet planet){if(planet==null)return;state.target=planet.id;state.focused="";hint="";fly(scene.destination(planet,UniverseScene.clickedDiameter(w(),h()),w(),h()));}
    void navigatePlanet(UniverseScene.Planet planet){if(!mind){approach(planet);return;}state.expanded.add("root");state.expanded.add("system:"+planet.galaxy);layoutTree();state.selectedTree="planet:"+planet.id;centerBox(state.selectedTree);}
    void reset(){pause();state.focused="";state.target="";hint="";if(mind){state.expanded.clear();state.expanded.add("root");state.selectedTree="";layoutTree();fitTree();invalidate();}else fly(scene.overview(w(),h()));}
    void zoomBy(double factor){pause();cancelFlight();if(mind){double next=Math.max(.001,Math.min(4,state.treeZoom*factor)),r=next/state.treeZoom;state.panX*=r;state.panY*=r;state.treeZoom=next;}else scene.magnify(factor,scene.planet(state.target),w(),h());invalidate();}
    void focus(String id){UniverseScene.Planet planet=scene.owner.get(id);UniverseScene.Node node=scene.nodes.get(id);if(planet==null||node==null)return;pause();if(mind){String key="point:"+id;Branch b=branches.get(key);while(b!=null&&b.parent!=null){state.expanded.add(b.parent);b=branches.get(b.parent);}layoutTree();state.focused=id;state.selectedTree="";centerBox(key);}else{state.target=planet.id;state.focused=id;state.rotations.put(planet.id,UniverseScene.Rotation.face(node.unit));fly(scene.destination(planet,Math.min(w()*.86,Math.max(220,h()-190)*.86)*2.5,w(),h()));}invalidate();}
    UniverseScene.Planet planetAt(double x,double y){UniverseScene.Planet best=null;double front=-1e99;for(UniverseScene.Planet p:scene.planets){UniverseScene.Projection s=scene.project(p,w(),h());if(s!=null&&Math.hypot(x-s.x,y-s.y)<=Math.max(18,s.r+8)&&s.depth>front){best=p;front=s.depth;}}return best;}
    private void tap(float x,float y){pause();if(mind){tapTree(x,y);return;}UniverseScene.Planet planet=planetAt(x,y);if(planet!=null){UniverseScene.Projection projected=scene.project(planet,w(),h());if(!planet.id.equals(state.target)||projected.r*2<UniverseScene.reveal(w(),h())){approach(planet);return;}LeafHit nearest=null;double distance=26;for(LeafHit hit:leafHits)if(hit.planet==planet){double d=Math.hypot(x-hit.x,y-hit.y);if(d<distance){distance=d;nearest=hit;}}if(nearest!=null){if(nearest.cluster.members.size()==1){String id=nearest.cluster.members.get(0).point.id;state.focused=id;select.accept(id);}else{hint="放大查看 "+nearest.cluster.members.size()+" 条想法";invalidate();}}else if(Math.hypot(projected.x-w()/2,projected.y-h()/2)>15)approach(planet);return;}
        List<Integer> hits=new ArrayList<>();for(int g=0;g<scene.systemCount();g++){UniverseScene.V v=scene.system(g);double gap=state.distance-v.z;if(gap<=0)continue;double scale=Math.min(w(),h())*1.15/gap,cx=w()/2+(v.x-state.cameraX)*scale,cy=h()/2-(v.y-state.cameraY)*scale;double radius=0;for(UniverseScene.Planet p:scene.planets)if(p.galaxy==g)radius=Math.max(radius,scene.orbitRadius(p));int count=0;for(UniverseScene.Planet p:scene.planets)if(p.galaxy==g)count+=p.nodes.size();if(Math.hypot(x-cx,y-cy)<=Math.max(24,UniverseScene.starRadius(count,scale)+8)||Math.hypot((x-cx)/Math.max(1,radius*scale),(y-cy)/Math.max(1,radius*scale*.62))<=1.2)hits.add(g);}if(hits.size()==1)approachSystem(hits.get(0));else if(hits.size()>1){String[] values=new String[hits.size()];for(int i=0;i<values.length;i++)values[i]="恒星系 "+(hits.get(i)+1);AlertDialog d=new AlertDialog.Builder(getContext()).setTitle("选择要靠近的恒星系").setItems(values,(dialog,i)->approachSystem(hits.get(i))).setNegativeButton("取消",null).create();dialogs.add(d);d.show();}}
    private void approachSystem(int system){state.target="";state.focused="";UniverseScene.V v=scene.system(system);double radius=0;for(UniverseScene.Planet p:scene.planets)if(p.galaxy==system)radius=Math.max(radius,scene.orbitRadius(p)+p.radius);fly(new double[]{v.x,v.y,v.z+Math.max(4,radius*2.8)});}
    private void beginPinch(MotionEvent e,int excluded){int first=-1,second=-1;for(int i=0;i<e.getPointerCount();i++)if(i!=excluded){if(first<0)first=i;else{second=i;break;}}if(second<0){pinching=false;return;}pinchFirst=e.getPointerId(first);pinchSecond=e.getPointerId(second);previousSpan=Math.hypot(e.getX(first)-e.getX(second),e.getY(first)-e.getY(second))/density;pinching=true;float x=(e.getX(first)+e.getX(second))/(2*density),y=(e.getY(first)+e.getY(second))/(2*density);scaleTarget=planetAt(x,y);if(scaleTarget==null)scaleTarget=scene.planet(state.target);}
    private void pinch(MotionEvent e){int a=e.findPointerIndex(pinchFirst),b=e.findPointerIndex(pinchSecond);if(a<0||b<0){beginPinch(e,-1);return;}double span=Math.hypot(e.getX(a)-e.getX(b),e.getY(a)-e.getY(b))/density;if(span<4||previousSpan<4){previousSpan=span;return;}double factor=span/previousSpan;previousSpan=span;if(mind){double next=Math.max(.001,Math.min(4,state.treeZoom*factor)),ratio=next/state.treeZoom,ax=(e.getX(a)+e.getX(b))/(2*density)-w()/2,ay=(e.getY(a)+e.getY(b))/(2*density)-h()/2;state.panX=ax-(ax-state.panX)*ratio;state.panY=ay-(ay-state.panY)*ratio;state.treeZoom=next;}else scene.magnify(factor,scaleTarget,w(),h());invalidate();}
    @Override public boolean onTouchEvent(MotionEvent e){float x=e.getX()/density,y=e.getY()/density;int action=e.getActionMasked();
        if(action==MotionEvent.ACTION_DOWN){pause();cancelFlight();multi=false;pinching=false;dragging=false;downX=lastX=x;downY=lastY=y;dragged=planetAt(x,y);if(dragged!=null){UniverseScene.Projection p=scene.project(dragged,w(),h());if(p==null||p.r*2<UniverseScene.reveal(w(),h()))dragged=null;}if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(true);}
        if(action==MotionEvent.ACTION_POINTER_DOWN){multi=true;pause();cancelFlight();if(!pinching)beginPinch(e,-1);}
        if(action==MotionEvent.ACTION_MOVE){if(e.getPointerCount()>=2){multi=true;if(!pinching)beginPinch(e,-1);else pinch(e);}else{if(Math.hypot(x-downX,y-downY)>5)dragging=true;if(!multi&&dragging){float dx=x-lastX,dy=y-lastY;if(mind){state.panX+=dx;state.panY+=dy;}else if(dragged!=null){UniverseScene.Projection p=scene.project(dragged,w(),h());if(p!=null){state.target=dragged.id;scene.rotate(dragged,dx,dy,p.r);}}else scene.pan(dx,dy,w(),h());invalidate();}}lastX=x;lastY=y;}
        if(action==MotionEvent.ACTION_POINTER_UP){int removed=e.getPointerId(e.getActionIndex());if(removed==pinchFirst||removed==pinchSecond)beginPinch(e,e.getActionIndex());}
        gestures.onTouchEvent(e);if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){pinching=false;dragged=null;if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(false);}return true;
    }
    @Override public boolean performClick(){super.performClick();return true;}
    private void color(int c){paint.setShader(null);paint.setStyle(Paint.Style.FILL);paint.setColor(c);}
    private void text(Canvas c,String value,float x,float y,float size,int color){color(color);paint.setTextSize(size);c.drawText(value,x,y,paint);}
    private String shortText(String s,int n){return s.codePointCount(0,s.length())>n?TitleGeneration.prefix(s,n)+"…":s;}
    @Override protected void onDraw(Canvas raw){super.onDraw(raw);raw.save();raw.scale(density,density);raw.drawColor(0xff070514);leafHits.clear();if(mind)drawTree(raw);else drawUniverse(raw);raw.restore();}
    private int tint(String id){return Color.HSVToColor(new float[]{Math.floorMod(id.hashCode()*47,360),.65f,.95f});}
    private void drawUniverse(Canvas c){color(0xff69617d);for(int i=0;i<120;i++){float x=(float)((i*97.337%100)*w()/100),y=(float)((i*41.791%100)*h()/100);c.drawCircle(x,y,i%9==0?1.2f:.6f,paint);}for(int g=0;g<scene.systemCount();g++)drawSystem(c,g);List<UniverseScene.Planet> ordered=new ArrayList<>(scene.planets);ordered.sort(Comparator.comparingDouble(p->scene.world(p).z));for(UniverseScene.Planet planet:ordered){UniverseScene.Projection p=scene.project(planet,w(),h());if(p==null||p.x+p.r<0||p.x-p.r>w()||p.y+p.r<0||p.y-p.r>h())continue;drawPlanet(c,planet,p);}color(0xbb000000);c.drawRoundRect(new RectF(5,5,w()-5,69),10,10,paint);String level="宇宙";UniverseScene.Planet target=scene.planet(state.target);if(target!=null){UniverseScene.Projection p=scene.project(target,w(),h());if(p!=null&&p.r*2>=UniverseScene.reveal(w(),h()))level=target.name;}text(c,shortText(level,26),12,22,13,0xfff0ecff);text(c,"点星球直达地图 · 用目录直达分类和主题",12,41,10,0xffaaa5bd);text(c,scene.systemCount()+" 恒星系 · "+scene.planets.size()+" 行星",12,58,10,0xffaaa5bd);if(!hint.isEmpty())text(c,hint,14,h()-18,12,0xffffd971);}
    private void drawSystem(Canvas c,int system){UniverseScene.V center=scene.system(system);double gap=state.distance-center.z;if(gap<=.05)return;double s=Math.min(w(),h())*1.15/gap;float x=(float)(w()/2+(center.x-state.cameraX)*s),y=(float)(h()/2-(center.y-state.cameraY)*s);for(UniverseScene.Planet planet:scene.planets)if(planet.galaxy==system){Path path=new Path();boolean open=false;double radius=scene.orbitRadius(planet);for(int i=0;i<=72;i++){double a=i*Math.PI*2/72,depth=state.distance-(center.z+Math.sin(a)*radius*.35);if(depth<=.05){open=false;continue;}double scale=Math.min(w(),h())*1.15/depth;float px=(float)(w()/2+(center.x+Math.cos(a)*radius-state.cameraX)*scale),py=(float)(h()/2-(center.y+Math.sin(a)*radius*.62-state.cameraY)*scale);if(!open){path.moveTo(px,py);open=true;}else path.lineTo(px,py);}color(0x335a6295);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(.7f);c.drawPath(path,paint);}int count=0;for(UniverseScene.Planet p:scene.planets)if(p.galaxy==system)count+=p.nodes.size();float star=(float)UniverseScene.starRadius(count,s);paint.setStyle(Paint.Style.FILL);paint.setColor(Color.WHITE);paint.setShader(new RadialGradient(x,y,star*3.2f,new int[]{0x88ffd76a,0x22ff9b37,0x00ff9b37},new float[]{0,.4f,1},Shader.TileMode.CLAMP));c.drawCircle(x,y,star*3.2f,paint);paint.setShader(new RadialGradient(x-star*.2f,y-star*.2f,star*1.6f,new int[]{Color.WHITE,0xffffdc78,0xffef8934},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,star,paint);paint.setShader(null);text(c,"恒星 "+(system+1),x-star,y+star+15,11,0xffffdc86);}
    private void drawPlanet(Canvas c,UniverseScene.Planet planet,UniverseScene.Projection p){float x=(float)p.x,y=(float)p.y,r=(float)Math.min(1e6,p.r);int tint=tint(planet.id);paint.setShader(new RadialGradient(x-r*.3f,y-r*.3f,Math.max(1,r*1.4f),new int[]{tint,0xff101027},null,Shader.TileMode.CLAMP));paint.setStyle(Paint.Style.FILL);c.drawCircle(x,y,r,paint);paint.setShader(null);color(0x887b8aa7);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1);c.drawCircle(x,y,r,paint);paint.setStyle(Paint.Style.FILL);if(r*2>=UniverseScene.reveal(w(),h())){c.save();c.clipPath(circle(x,y,r));drawGrid(c,planet,p);for(UniverseScene.Cluster group:scene.clusters(planet,p.r)){UniverseScene.V v=scene.rotation(planet).apply(group.unit);if(v.z<0)continue;float px=x+(float)v.x*r,py=y-(float)v.y*r;boolean focused=group.members.size()==1&&group.members.get(0).point.id.equals(state.focused);color(focused?0xffffd971:group.members.size()>1?0xff9f9af5:0xfff4efff);float radius=group.members.size()>1?Math.min(25,11+(float)Math.sqrt(group.members.size())*3.5f):focused?6:3.5f;c.drawCircle(px,py,radius,paint);if(group.members.size()>1)text(c,Integer.toString(group.members.size()),px-radius*.35f,py+4,12,Color.WHITE);else if(focused||r>250)text(c,shortText(group.members.get(0).point.title,16),px+10,py-7,12,focused?0xffffd971:0xffeeeaff);leafHits.add(new LeafHit(planet,group,px,py));}c.restore();}text(c,shortText(planet.name,20),x-r,Math.max(78,y-r-10),r>150?15:11,0xfff2efff);}
    private Path circle(float x,float y,float r){Path path=new Path();path.addCircle(x,y,r,Path.Direction.CW);return path;}
    private void drawGrid(Canvas c,UniverseScene.Planet planet,UniverseScene.Projection p){for(int axis=0;axis<2;axis++)for(int line=-60;line<=60;line+=30){Path path=new Path();boolean visible=false;for(int step=-180;step<=180;step+=4){double lat=Math.toRadians(axis==0?line:step/2.0),lon=Math.toRadians(axis==0?step:line*2);UniverseScene.V unit=new UniverseScene.V(Math.cos(lat)*Math.sin(lon),Math.sin(lat),Math.cos(lat)*Math.cos(lon));UniverseScene.V v=scene.rotation(planet).apply(unit);if(v.z>=0){float x=(float)(p.x+v.x*p.r),y=(float)(p.y-v.y*p.r);if(!visible)path.moveTo(x,y);else path.lineTo(x,y);visible=true;}else visible=false;}color(line==0?0x5548d2df:0x3348d2df);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(.7f);c.drawPath(path,paint);}paint.setStyle(Paint.Style.FILL);}
    private void addBranch(Branch b){branches.put(b.id,b);if(b.parent!=null)branches.get(b.parent).children.add(b.id);}
    private void buildTree(){addBranch(new Branch("root","我的宇宙","地图层级",null,null,scene.nodes.size()));for(int g=0;g<scene.systemCount();g++){int count=0;for(UniverseScene.Planet p:scene.planets)if(p.galaxy==g)count+=p.nodes.size();addBranch(new Branch("system:"+g,"恒星系 "+(g+1),"恒星系","root",null,count));}for(UniverseScene.Planet planet:scene.planets){String id="planet:"+planet.id;addBranch(new Branch(id,planet.name,"行星","system:"+planet.galaxy,null,planet.nodes.size()));Map<String,List<UniverseScene.Node>> topics=new TreeMap<>();for(UniverseScene.Node n:planet.nodes)topics.computeIfAbsent(n.topic,k->new ArrayList<>()).add(n);for(Map.Entry<String,List<UniverseScene.Node>> e:topics.entrySet()){String key=id+"/topic:"+e.getKey();addBranch(new Branch(key,e.getKey(),"主题",id,null,e.getValue().size()));for(UniverseScene.Node n:e.getValue())addBranch(new Branch("point:"+n.point.id,n.point.title,"Point",key,n.point.id,1));}}if(state.expanded.isEmpty())state.expanded.add("root");layoutTree();}
    private float height(String id){Branch b=branches.get(id);if(!state.expanded.contains(id)||b.children.isEmpty())return 86;float height=0;for(String child:b.children)height+=height(child);return Math.max(86,height);}
    private void place(String id,float x,float top){Branch b=branches.get(id);float total=height(id);Box box=new Box(id,x,top+total/2);boxes.add(box);boxIndex.put(id,box);if(state.expanded.contains(id)){float y=top;for(String child:b.children){place(child,x+264,y);y+=height(child);}}}
    private void layoutTree(){boxes.clear();boxIndex.clear();place("root",0,0);}
    private Box box(String id){return boxIndex.get(id);}
    private void fitTree(){if(boxes.isEmpty()||w()<=0||h()<=0)return;float minX=Float.MAX_VALUE,maxX=-minX,minY=minX,maxY=-minX;for(Box b:boxes){minX=Math.min(minX,b.x-106);maxX=Math.max(maxX,b.x+106);minY=Math.min(minY,b.y-34);maxY=Math.max(maxY,b.y+34);}state.treeZoom=Math.min(1,Math.max(.001,Math.min((w()-32)/Math.max(1,maxX-minX),(h()-80)/Math.max(1,maxY-minY))));state.panX=-(minX+maxX)/2*state.treeZoom;state.panY=-(minY+maxY)/2*state.treeZoom;}
    private void centerBox(String id){Box b=box(id);if(b==null)return;state.treeZoom=Math.max(.1,Math.min(1.4,Math.min((w()-32)/240,(h()-120)/100)));state.panX=-b.x*state.treeZoom;state.panY=-b.y*state.treeZoom;invalidate();}
    private RectF rect(Box b){float z=(float)state.treeZoom,x=(float)(w()/2+b.x*z+state.panX),y=(float)(h()/2+b.y*z+state.panY);return new RectF(x-106*z,y-34*z,x+106*z,y+34*z);}
    private void toggle(String id){Box before=box(id);if(state.expanded.contains(id))state.expanded.remove(id);else state.expanded.add(id);layoutTree();Box after=box(id);if(before!=null&&after!=null){state.panX+=(before.x-after.x)*state.treeZoom;state.panY+=(before.y-after.y)*state.treeZoom;}state.selectedTree="";invalidate();}
    private void tapTree(float x,float y){if(detailOpen.contains(x,y)){Branch selected=branches.get(state.selectedTree);if(selected!=null&&selected.point!=null)select.accept(selected.point);return;}for(int i=boxes.size()-1;i>=0;i--){Box b=boxes.get(i);RectF r=rect(b);if(!r.contains(x,y))continue;Branch branch=branches.get(b.id);if(!branch.children.isEmpty()&&x>r.right-38*state.treeZoom){toggle(b.id);return;}state.selectedTree=b.id;state.focused=branch.point==null?"":branch.point;centerBox(b.id);return;}state.selectedTree="";invalidate();}
    private void drawTree(Canvas c){for(Box b:boxes){Branch branch=branches.get(b.id);Box parent=box(branch.parent);if(parent!=null){RectF a=rect(parent),r=rect(b);color(0x5560becf);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1);Path path=new Path();path.moveTo(a.right,a.centerY());path.cubicTo((a.right+r.left)/2,a.centerY(),(a.right+r.left)/2,r.centerY(),r.left,r.centerY());c.drawPath(path,paint);}}
        float z=(float)state.treeZoom;for(Box b:boxes){RectF r=rect(b);if(r.right<0||r.left>w()||r.bottom<0||r.top>h())continue;Branch branch=branches.get(b.id);color(branch.point==null?0xff454198:0xff15434c);c.drawRoundRect(r,12*z,12*z,paint);if(b.id.equals(state.selectedTree)||Objects.equals(branch.point,state.focused)){color(0xffffd971);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2);c.drawRoundRect(r,12*z,12*z,paint);}text(c,shortText(branch.title,13),r.left+10*z,r.centerY()-4*z,14*z,Color.WHITE);text(c,branch.level+" · "+branch.count+(branch.point==null?"条":" · 查看原文"),r.left+10*z,r.centerY()+17*z,10*z,0xffc5d9df);if(!branch.children.isEmpty())text(c,state.expanded.contains(b.id)?"−":"+",r.right-28*z,r.centerY()+6*z,22*z,Color.WHITE);}
        detailOpen.setEmpty();Branch selected=branches.get(state.selectedTree);if(selected!=null){color(0xee11142c);c.drawRoundRect(new RectF(8,h()-100,w()-8,h()-5),12,12,paint);text(c,shortText(selected.title,23),18,h()-76,14,Color.WHITE);List<String> path=new ArrayList<>();Branch b=selected;while(b!=null){path.add(b.title);b=branches.get(b.parent);}Collections.reverse(path);text(c,shortText(String.join(" › ",path),42),18,h()-54,10,0xffaaa5bd);if(selected.point!=null){detailOpen.set(12,h()-44,w()-12,h()-8);text(c,"查看原文",20,h()-20,14,0xffaaa0ff);}else text(c,selected.level+" · "+selected.count+" 条 Point · 只读浏览",18,h()-22,12,0xffc4bedc);}}
    void showNavigator(){pause();LinearLayout form=new LinearLayout(getContext());form.setOrientation(LinearLayout.VERTICAL);form.setPadding((int)(12*density),0,(int)(12*density),0);EditText query=new EditText(getContext());query.setSingleLine(true);query.setHint("搜索星球、分类、主题或内容");form.addView(query);ScrollView scroll=new ScrollView(getContext());LinearLayout results=new LinearLayout(getContext());results.setOrientation(LinearLayout.VERTICAL);scroll.addView(results);form.addView(scroll,new LinearLayout.LayoutParams(-1,(int)(350*density)));AlertDialog dialog=new AlertDialog.Builder(getContext()).setTitle("宇宙目录").setView(form).setNegativeButton("关闭",null).create();Runnable refresh=()->{results.removeAllViews();String q=query.getText().toString().trim().toLowerCase(Locale.ROOT);int matches=0;for(UniverseScene.Planet planet:scene.planets){if(q.isEmpty()||planet.name.toLowerCase(Locale.ROOT).contains(q)){navButton(results,planet.name+" · "+planet.nodes.size()+" 条",()->{dialog.dismiss();if(mind){state.expanded.add("root");state.expanded.add("system:"+planet.galaxy);layoutTree();state.selectedTree="planet:"+planet.id;centerBox(state.selectedTree);}else approach(planet);});matches++;}Map<String,UniverseScene.Node> topics=new TreeMap<>();for(UniverseScene.Node n:planet.nodes)topics.putIfAbsent(n.topic,n);for(Map.Entry<String,UniverseScene.Node> topic:topics.entrySet())if(q.isEmpty()||topic.getKey().toLowerCase(Locale.ROOT).contains(q)){navButton(results,"主题 · "+topic.getKey()+" / "+planet.name,()->{dialog.dismiss();focus(topic.getValue().point.id);});matches++;}if(!q.isEmpty())for(UniverseScene.Node node:planet.nodes)if((node.point.title+" "+node.point.context()).toLowerCase(Locale.ROOT).contains(q)){navButton(results,"想法 · "+node.point.title,()->{dialog.dismiss();select.accept(node.point.id);});matches++;}}if(matches==0){TextView empty=new TextView(getContext());empty.setText("没有找到相关内容");results.addView(empty);}};query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){refresh.run();}public void afterTextChanged(Editable e){}});refresh.run();dialogs.add(dialog);dialog.show();}
    private void navButton(LinearLayout body,String title,Runnable action){Button button=new Button(getContext());button.setText(title);button.setAllCaps(false);button.setOnClickListener(v->action.run());body.addView(button);}
}
